(function(){if(document.getElementById('ccs-clarity-1'))return;var s=document.createElement('style');s.id='ccs-clarity-1';s.textContent="#cc-staff,#cc-staff .ccs-app{background:#f4f3ef}#cc-staff .ccs-side{background:#fff;border-right:1px solid #e4e0da}#cc-staff .ccs-amlist li span,#cc-staff .ccs-sub{color:#57514c}#cc-staff .ccs-tabs{display:inline-flex;flex-wrap:wrap;gap:4px;padding:4px;background:#fff;border:1px solid #e4e0da;border-radius:14px;box-shadow:0 1px 2px rgba(31,35,28,.04);margin-bottom:6px;max-width:100%}#cc-staff .ccs-tab{appearance:none;border:0;background:0 0;color:#3f3a36;font-weight:600;font-size:15px;min-height:42px;padding:8px 14px;border-radius:10px;cursor:pointer;display:inline-flex;align-items:center;gap:8px;transition:background-color .15s,color .15s}#cc-staff .ccs-tab:hover{background:#f1f3ec;color:#2b2622}#cc-staff .ccs-tab[aria-pressed=true]{background:#5f7a4a;color:#fff}#cc-staff .ccs-tab .ccs-n{min-width:24px;padding:1px 7px;border-radius:99px;background:#ece9e4;color:#3f3a36;font-size:13px;font-weight:700;text-align:center;font-variant-numeric:tabular-nums}#cc-staff .ccs-tab[aria-pressed=true] .ccs-n{background:rgba(255,255,255,.22);color:#fff}#cc-staff .ccs-day{display:flex;align-items:baseline;gap:10px;margin:22px 0 10px;font-size:13.5px;letter-spacing:.06em;color:#2b2622}#cc-staff .ccs-day em{font-style:normal;letter-spacing:0;text-transform:none;font-weight:600;color:#6b6560;font-size:14px}@media (min-width:760px){#cc-staff .ccs-day{position:sticky;top:0;z-index:5;background:#f4f3ef;padding:10px 0 8px;margin:12px 0 6px}}#cc-staff .ccs-list{gap:10px}#cc-staff .ccs-card{background:#fff;border:1px solid #e4e0da;box-shadow:0 1px 2px rgba(31,35,28,.05),0 4px 14px -10px rgba(31,35,28,.18);padding:16px 20px 16px 22px}";document.head.appendChild(s);})();